function normalizeRouteAuthz(route, id, isPage, auth, context) {
    if ('access' in route) {
        throw new Error(`Client route "${id}" uses removed access; declare authz instead.`);
    }
    const value = 'authz' in route ? route.authz : undefined;
    if (value !== undefined) {
        if (!isPage)
            throw new Error(`Client route group "${id}" cannot declare authz.`);
        if (value === 'skip')
            return value;
        if (!value ||
            typeof value !== 'object' ||
            !('resource' in value) ||
            !value.resource ||
            typeof value.resource !== 'object' ||
            typeof value.resource.type !== 'string' ||
            !value.resource.type.trim() ||
            typeof value.resource.id !== 'string' ||
            !value.resource.id.trim() ||
            typeof value.action !== 'string' ||
            !value.action.trim())
            throw new Error(`Client route "${id}" must use authz "skip" or { resource: { type, id }, action }.`);
        return Object.freeze({
            resource: Object.freeze({ ...value.resource }),
            action: value.action,
        });
    }
    return isPage &&
        auth === 'required' &&
        context.surface === 'app' &&
        !context.hasPageAncestor
        ? Object.freeze({
            resource: Object.freeze({ type: 'page', id: route.name.trim() }),
            action: 'access',
        })
        : 'skip';
}

